import{z as E,x as p,o as n,c as m,q as s,j as i,D as t,d as e,s as l,S as d,b as r}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"支配与 φ","description":"","frontmatter":{"title":"支配与 φ","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dominator-phi.md","filePath":"cs/dominator-phi.md","lastUpdated":1791063341000}'),A={name:"cs/dominator-phi.md"};function h(D,a,B,F,u,S){const o=p("Mermaid");return n(),m("div",null,[a[2]||(a[2]=s('<h1 id="支配与-φ" tabindex="-1">支配与 φ <a class="header-anchor" href="#支配与-φ" aria-label="Permalink to &quot;支配与 φ&quot;">​</a></h1><div class="epigraph"><p>$d$ 支配 $n$ 当每条从入口到 $n$ 的路都经过 $d$；支配边界是插入 φ 的位置，使汇合处每个名字仍只赋值一次。</p><footer>—— 据 Lengauer and Tarjan, A Fast Algorithm for Finding Dominators in a Flowgraph, 1979；Cytron et al., 1991 整理</footer></div><p>上一课<a href="/cs/ssa-form">SSA</a>已经声明：改名、φ 按支配边界放置，Cytron 高效，本课要直觉。SSA 课把 φ 当语义，支配一笔带过。本课不重写「一次赋值一名」。缺口是支配树与支配边界 \\(\\mathrm{DF}\\)：为何 φ 插在那里就不多不少。后课活跃变量在这张已改名的图上算区间。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>入口 \\(s\\) 支配所有可达块。严格支配：排除自身。直接支配 \\(\\mathrm{idom}(n)\\) 是严格支配 \\(n\\) 的最「近」者，全体 \\(\\mathrm{idom}\\) 成树。支配边界：被 \\(n\\) 支配的块的后继里，那些<strong>不再</strong>被 \\(n\\) 严格支配的块——恰是「有的前驱带着 \\(n\\) 的定值、有的没有」的入口。对变量 \\(x\\) 的每个定值块，在 \\(\\mathrm{DF}\\) 插 \\(\\phi\\)，再迭代（φ 自己也是定值）。</p><p>缺口是这一定义，不是再解释 φ 要在后端拆掉。Lengauer–Tarjan 用 DFS 半支配在几乎线性时间算 \\(\\mathrm{idom}\\)；本课认算法名，不证。</p><h3 id="支配不是后支配" tabindex="-1">支配不是后支配 <a class="header-anchor" href="#支配不是后支配" aria-label="Permalink to &quot;支配不是后支配&quot;">​</a></h3><p>后支配是到出口的对偶，用于部分死代码、控制依赖。φ 放置用正向支配。不要把「必经出口」当 DF。</p><p><span class="marginnote">Lengauer–Tarjan 1979。Cytron et al. 1991 把 DF 与 SSA 连起来。Appel 1998 把 SSA 比作函数式。SSA 课已引二者；本课把树与边界写清，供数据流课默认「标量名已唯一」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>算支配树（迭代交或 LT）。对每个变量的定值集求 DF 并插 φ。按支配序重命名栈：进入块 push 新名，离开 pop。φ 的第 \\(i\\) 个操作数来自第 \\(i\\) 个前驱的当前名。</p>',11)),(n(),i(d,null,{default:t(()=>[l(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CFG%5B%22CFG%22%5D%20--%3E%20ID%5B%22%E6%94%AF%E9%85%8D%E6%A0%91%22%5D%0A%20%20ID%20--%3E%20DF%5B%22%E6%94%AF%E9%85%8D%E8%BE%B9%E7%95%8C%22%5D%0A%20%20DF%20--%3E%20PHI%5B%22%E6%8F%92%20%CF%86%22%5D%0A%20%20PHI%20--%3E%20RNM%5B%22%E6%8C%89%E6%94%AF%E9%85%8D%E5%BA%8F%E6%94%B9%E5%90%8D%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("p",null,"不可约 CFG 仍有支配树；DF 可能更肥，φ 更多，不要求先可约。",-1)),a[4]||(a[4]=r("h2",{id:"机制",tabindex:"-1"},[e("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=r("p",null,[e("剪枝 SSA：若定值从不在支配范围内被读，可不插。半剪枝用全局活跃，完整剪枝更贵。本课默认至少半剪枝直觉。φ 不是 ISA 指令：后课分配前在前驱末插 "),r("code",null,"move"),e("。")],-1)),(n(),i(d,null,{default:t(()=>[l(o,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%85%A5%E5%8F%A3%20s%22%5D%20--%3E%20A%5B%22%E5%9D%97%20a%EF%BC%9A%E5%AE%9A%E4%B9%89%20x%22%5D%0A%20%20S%20--%3E%20B%5B%22%E5%9D%97%20b%EF%BC%9A%E4%B8%8D%E8%B5%B0%20a%22%5D%0A%20%20A%20--%3E%20J%5B%22%E6%B1%87%E5%90%88%E5%9D%97%20j%22%5D%0A%20%20B%20--%3E%20J%0A%20%20J%20--%3E%7C%22j%20%E6%98%AF%20a%20%E7%9A%84%E6%94%AF%E9%85%8D%E8%BE%B9%E7%95%8C%EF%BC%9A%CF%86%20x%20%E5%9C%A8%E6%AD%A4%22%7C%20PHI%5B%22phi%20%3D%20a%20%E8%B7%AF%E5%BE%84%E7%9A%84%20x%20%E6%88%96%20b%20%E8%B7%AF%E5%BE%84%E7%9A%84%20x%22%5D%0A%20%20S%20--%3E%7C%22s%20%E6%94%AF%E9%85%8D%20j%EF%BC%8C%E6%95%85%20j%20%E4%B8%8D%E5%9C%A8%20s%20%E7%9A%84%E8%BE%B9%E7%95%8C%22%7C%20J%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">数字实例：取最简单的菱形——入口 s 分叉到 a、b，两路在 j 汇合。a 定义了 x，从 a 来的路带着 x，从 b 来的路没带，所以 j 是 a 的支配边界，φ 就插在 j 入口。而 s 支配 j（每条到 j 的路都过 s），j 不在 s 的边界里，s 也就不需要 φ。</span></p><p><span class="marginnote">直觉类比：支配关系像「必经之门」——从城市入口到某个房间的每条路都穿过同一扇门，这扇门就支配那个房间；idom 是离房间最近的必经门。把每扇「最近的必经门」连起来，就是一棵树：支配树。</span></p><p>与<a href="/cs/dfs-edge-types">DFS 边分类</a>：支配算法用 DFS 树；回边与支配关系相关但不是同一分类。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p><span class="marginnote">常见误区：支配不是后支配。支配问「从入口出发必经谁」，后支配问「到出口必经谁」，方向相反，用途也不同——φ 放置只用正向支配，「必经出口」和支配边界 DF 是两回事，混用会插错位置。</span></p><p>本课不算 <code>in/out</code> 活跃方程。不做 memory SSA。后课默认：标量已是 SSA，汇合点有 φ。数据流框架以活跃变量为代表下一课补——冲突图要的是同时活，不是支配。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>支配树给出 idom；DF 决定 φ 的位置。</li><li>改名沿支配序；φ 后端再拆。</li><li>活跃区间仍是下一课的对象。</li><li>出处：Lengauer and Tarjan, 1979；Cytron et al., 1991。</li></ul>',8))])}const f=E(A,[["render",h]]);export{C as __pageData,f as default};
